import os
cmds=['cmd.usage.refresh','cmd.usage.export','cmd.account.select_profile','cmd.provider.switch_route','cmd.usage.view_budget','cmd.provider.retry_after']
tot={c:[0,0] for c in cmds}
for root,dirs,files in os.walk('Plans'):
    for f in files:
        p=os.path.join(root,f)
        t=open(p,encoding='utf-8',errors='replace').read()
        for c in cmds:
            n=t.count(c)
            tot[c][0]+=n
            if not p.startswith('Plans/_shards'): tot[c][1]+=n
for c in cmds: print(c, tot[c])
